// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/{modality}/providers", wrapper.ListProviders)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/{modality}/routes/{target}", wrapper.ResolveTarget)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/{modality}/stats", wrapper.GetStats)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/{modality}/stats/tags", wrapper.GetTagStats)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/turns/stats", wrapper.GetTurnStats)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/phone/vendors", wrapper.ListPhoneVendors)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/phone/numbers/available", wrapper.SearchPhoneNumbers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/phone/numbers", wrapper.ListPhoneNumbers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/phone/numbers", wrapper.BuyPhoneNumber)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/phone/numbers/{e164}", wrapper.ReleasePhoneNumber)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/phone/numbers/{e164}/attach", wrapper.AttachPhoneNumber)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/phone/calls", wrapper.PlacePhoneCall)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/stats/rollup", wrapper.RunRollup)

	return m
}

