// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Liveness and dependency check
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// PlacePhoneCall Place an outbound call and bridge it into a Stream call
	// (POST /v1/phone/calls)
	PlacePhoneCall(ctx context.Context, request PlacePhoneCallRequestObject) (PlacePhoneCallResponseObject, error)
	// ListPhoneNumbers The numbers the calling customer holds
	// (GET /v1/phone/numbers)
	ListPhoneNumbers(ctx context.Context, request ListPhoneNumbersRequestObject) (ListPhoneNumbersResponseObject, error)
	// BuyPhoneNumber Buy a number, which starts its monthly charge
	// (POST /v1/phone/numbers)
	BuyPhoneNumber(ctx context.Context, request BuyPhoneNumberRequestObject) (BuyPhoneNumberResponseObject, error)
	// SearchPhoneNumbers Search a vendor for numbers to buy
	// (GET /v1/phone/numbers/available)
	SearchPhoneNumbers(ctx context.Context, request SearchPhoneNumbersRequestObject) (SearchPhoneNumbersResponseObject, error)
	// ReleasePhoneNumber Give a number back, which stops its monthly charge
	// (DELETE /v1/phone/numbers/{e164})
	ReleasePhoneNumber(ctx context.Context, request ReleasePhoneNumberRequestObject) (ReleasePhoneNumberResponseObject, error)
	// AttachPhoneNumber Point a number at a Stream call
	// (POST /v1/phone/numbers/{e164}/attach)
	AttachPhoneNumber(ctx context.Context, request AttachPhoneNumberRequestObject) (AttachPhoneNumberResponseObject, error)
	// ListPhoneVendors List the telephony vendors and whether they can be used
	// (GET /v1/phone/vendors)
	ListPhoneVendors(ctx context.Context, request ListPhoneVendorsRequestObject) (ListPhoneVendorsResponseObject, error)
	// RunRollup Aggregate request rows into a rollup table
	// (POST /v1/stats/rollup)
	RunRollup(ctx context.Context, request RunRollupRequestObject) (RunRollupResponseObject, error)
	// GetTurnStats Conversational latency for the calling customer
	// (GET /v1/turns/stats)
	GetTurnStats(ctx context.Context, request GetTurnStatsRequestObject) (GetTurnStatsResponseObject, error)
	// ListProviders List the providers configured for a modality and their live health
	// (GET /v1/{modality}/providers)
	ListProviders(ctx context.Context, request ListProvidersRequestObject) (ListProvidersResponseObject, error)
	// ResolveTarget Resolve a provider name or capability shortcut to a ranked candidate list
	// (GET /v1/{modality}/routes/{target})
	ResolveTarget(ctx context.Context, request ResolveTargetRequestObject) (ResolveTargetResponseObject, error)
	// GetStats Aggregated usage for the calling customer
	// (GET /v1/{modality}/stats)
	GetStats(ctx context.Context, request GetStatsRequestObject) (GetStatsResponseObject, error)
	// GetTagStats Aggregated usage broken down by the values of one cost label
	// (GET /v1/{modality}/stats/tags)
	GetTagStats(ctx context.Context, request GetTagStatsRequestObject) (GetTagStatsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

